async function handleProviderLogin(update:any,provider:'kleinanzeigen'|'immomio'|'immoscout'|'immowelt'|'wg_gesucht'){
 let x:any=null;
 try{
  x=await validateUser(update,provider==='wg_gesucht');if(!x)return;
  const {ctx,chatId,messageId,user}=x,name=providerName(provider);
  let url:string;
  if(provider==='kleinanzeigen'){
   const result=await internal(APPLICATION_WORKER,{action:'login_share',userId:String(user.id),source:2,origin:'telegram',returnTarget:'telegram',context:{channel:'telegram',share_flow:true}});
   if(!result?.url)throw Error('auth_flow_create_failed');
   url=providerUrl(provider,result.url);
  }else if(provider==='immomio'){
   const connect=await createConnectTicket(String(user.id),provider),ticket=connect.state;
   url=`https://login.traumwohnunghamburg.de/connect?ticket=${encodeURIComponent(ticket)}`;
  }else{
   const connect=await createConnectTicket(String(user.id),provider),ticket=connect.state;
   url=`https://login.traumwohnunghamburg.de/connect?ticket=${encodeURIComponent(ticket)}`;
  }
  const copy=provider==='kleinanzeigen'
   ? `🔐 <b>Kleinanzeigen verbinden</b>\n\n1. Tippe unten auf <b>Kleinanzeigen verbinden</b>.\n2. Melde dich an.\n3. Tippe auf <b>Teilen</b> und sende den Link an <b>TraumWohnung Hamburg</b>.`
   : provider==='immomio'
    ? `🔐 <b>Immomio verbinden</b>\n\n1. Tippe unten auf <b>Immomio verbinden</b>.\n2. Melde dich bei Immomio an.\n3. Nach erfolgreichem Login wird die Verbindung automatisch erkannt und gespeichert.\n\nKein Teilen, kein Kopieren einer URL.`
    : provider==='immowelt'
     ? `🔐 <b>Immowelt verbinden</b>\n\n1. Tippe unten auf <b>Immowelt verbinden</b>.\n2. Melde dich an.\n3. Dein Konto wird automatisch verbunden.`
     : provider==='wg_gesucht'
      ? `🔐 <b>WG-Gesucht verbinden</b>\n\n1. Tippe unten auf <b>WG-Gesucht verbinden</b>.\n2. Melde dich mit E-Mail und Passwort an.\n3. Bestätige bei Bedarf den Code aus deiner E-Mail.\n\nDer Login ist auch ohne Premium möglich.`
      : `🔐 <b>ImmoScout24 verbinden</b>\n\n1. Tippe unten auf <b>ImmoScout24 verbinden</b>.\n2. Melde dich an.\n3. Dein Konto wird automatisch verbunden.`;
  await editOrSend(chatId,messageId,copy,[[{text:`🌐 ${name} verbinden`,url}],[{text:'← Automatische Bewerbung',callback_data:'platforms'}]]);
  await finish(ctx.updateId,ctx.claim,true);x=null;
 }catch(e){
  console.error(`${provider}_login_bridge`,String(e));
  const setupMissing=String(e).includes('oauth_client_not_provisioned');
  const detail=setupMissing?'Der direkte Kleinanzeigen-Login ist noch nicht vom Anbieter für unseren Web-Callback freigeschaltet.':'Bitte erneut versuchen.';
  if(x?.chatId&&x?.messageId)await editOrSend(x.chatId,x.messageId,`⚠️ <b>${providerName(provider)}-Login konnte nicht gestartet werden.</b>\n\n${detail}`,[[{text:'← Automatische Bewerbung',callback_data:'platforms'}]]).catch(()=>{});
