export async function setUserBlocked(userId, blocked) {
    const { data: target, error: targetError } = await db
        .from("bot_users")
        .select("id,telegram_user_id,is_active")
        .eq("id", userId)
        .maybeSingle();
    if (targetError)
        throw targetError;
    if (!target)
        throw new Error("user unavailable");
    if (isAdmin(target))
        throw new Error("admin accounts cannot be blocked");
    const { error } = await db
        .from("bot_users")
        .update({ is_active: !blocked, updated_at: new Date().toISOString() })
        .eq("id", userId);
    if (error)
        throw error;
    if (blocked) {
        const { error: profileError } = await db
            .from("search_profiles")
            .update({ is_active: false, updated_at: new Date().toISOString() })
            .eq("user_id", userId);
        if (profileError)
            throw profileError;
    }
}

export async function deleteUser(userId) {
    const { data: target, error: targetError } = await db
        .from("bot_users")
        .select("id,telegram_user_id")
        .eq("id", userId)
        .maybeSingle();
    if (targetError)
        throw targetError;
    if (!target)
        return;
    if (isAdmin(target))
        throw new Error("admin accounts cannot be deleted");
    await purgePlatformSessions(userId);
    const { error } = await db.from("bot_users").delete().eq("id", userId);
    if (error)
        throw error;
}

export async function setPlanOverride(userId, grant) {
    const plan = grant === "free" ? "free" : "premium";
    const expiresAt = adminGrantExpiry(grant);
    const { data: target, error } = await db
        .from("bot_users")
        .update({
        plan_override: plan,
        plan_override_expires_at: expiresAt,
        updated_at: new Date().toISOString(),
    })
        .eq("id", userId)
        .select("id,chat_id")
        .maybeSingle();
    if (error)
        throw error;
    if (!target)
        throw new Error("user unavailable");
    if (plan === "premium") {
        const { data: profiles, error: profileError } = await db
            .from("search_profiles")
            .select("id")
            .eq("user_id", userId);
        if (profileError)
            throw profileError;
        const profileIds = (profiles || []).map((profile) => profile.id);
        if (profileIds.length) {
            const { error: deliveryError } = await db
                .from("delivery_events")
                .update({ next_retry_at: null })
                .in("profile_id", profileIds)
                .eq("status", "pending");
            if (deliveryError)
                throw deliveryError;
        }
    }
    return target;
}


