    if (data === "language")
        return languagePage(user, chatId, messageId);
    if (data.startsWith("lang:")) {
        const code = data.slice(5);
        if (!["de", "en", "ckb", "ku", "prs", "fa", "ru", "tr", "ar"].includes(code))
            return;
        const { error } = await db.from("bot_users").update({ ui_language: code, updated_at: new Date().toISOString() }).eq("id", user.id);
        if (error)
            throw error;
        chatLanguages.set(chatId, code);
        return settings({ ...user, ui_language: code }, chatId, messageId);
    }
    if (data === "help") {
        return edit(chatId, messageId, HELP_TEXT, {
            inline_keyboard: [[button("← Zurück", "home")]],
        });
    }
    if (data === "premium") {
        if (query.message?.photo) {
            await telegram("deleteMessage", { chat_id: chatId, message_id: messageId }).catch(() => { });
            return premium(user, chatId);
        }
        return premium(user, chatId, messageId);
    }
    if (data === "portal") {
        if (query.message?.photo)
            await telegram("deleteMessage", { chat_id: chatId, message_id: messageId }).catch(() => { });
        const url = await secret("stripe_portal_url").catch(() => null);
        const valid = url && /^https:\/\/billing\.stripe\.com\//.test(url);
        return edit(chatId, messageId, valid
            ? "💳 <b>Abo verwalten</b>"
            : "💳 Das Stripe Customer Portal ist aktuell noch nicht konfiguriert.", {
            inline_keyboard: [
                ...(valid ? [[{ text: "💳 Abo verwalten", url }]] : []),
                [button("← Premium", "premium")],
            ],
        });
    }
    if (data === "pause") {
        await setPaused(user.id, true);
        return edit(chatId, messageId, "⏸ Dein Suchprofil ist pausiert.", homeKeyboard(user));
    }
    if (data === "resume") {
        await setPaused(user.id, false);
        return edit(chatId, messageId, "▶️ Dein Suchprofil ist wieder aktiv.", homeKeyboard(user));
    }
    if (data === "status")
        return renderStatus(user, chatId, messageId);
    const draft = draftFor(user);
    if (data === "types")
        return renderTypes(user, chatId, messageId, draft);
    if (data === "location")
        return renderLocation(user, chatId, messageId, draft);
    if (data === "boroughs") {
        return renderBoroughs(user, chatId, messageId, draft);
    }
    if (data === "neighborhoods") {
        return renderNeighborhoods(user, chatId, messageId, draft);
    }
    if (data === "rent")
        return renderRent(user, chatId, messageId, draft);
    if (data === "roomarea")
        return renderRooms(user, chatId, messageId, draft);
    if (data === "rooms")
        return renderRooms(user, chatId, messageId, draft);
    if (data === "area")
        return renderArea(user, chatId, messageId, draft);
    if (data.startsWith("edit:")) {
        draft.edit_return = true;
        const step = data.slice(5);
        if (step === "types")
            return renderTypes(user, chatId, messageId, draft);
        if (step === "location") {
            return renderLocation(user, chatId, messageId, draft);
        }
        if (step === "rent")
            return renderRent(user, chatId, messageId, draft);
        if (step === "roomarea")
            return renderRooms(user, chatId, messageId, draft);
        if (step === "rooms")
            return renderRooms(user, chatId, messageId, draft);
        if (step === "area")
            return renderArea(user, chatId, messageId, draft);
    }
    if (data.startsWith("type:")) {
        const value = data.slice(5);
        if (!PROPERTY_TYPES.includes(value)) {
            return renderTypes(user, chatId, messageId, draft);
        }
        const hadExistingLocation = ["all_hamburg", "boroughs", "neighborhoods"].includes(String(draft.location_mode || ""));
        const categoryEdit = draft.profile_edit === true || draft.edit_return === true;
        draft.property_types = [value];
        draft.min_rooms = null;
        draft.min_area_sqm = null;
        draft.min_room_area_sqm = null;
        if (categoryEdit) {
            delete draft.profile_edit;
            delete draft.edit_return;
        }
        return categoryEdit && hadExistingLocation
            ? renderRent(user, chatId, messageId, draft)
            : renderLocation(user, chatId, messageId, draft);
    }
    if (data.startsWith("loc:")) {
        const value = data.slice(4);
        if (value === "all") {
            draft.location_mode = "all_hamburg";
            draft.borough_ids = [];
            draft.neighborhood_ids = [];
            return afterSelection(user, chatId, messageId, draft, "rent");
        }
        if (value === "boroughs") {
            draft.location_mode = "boroughs";
            draft.neighborhood_ids = [];
            return renderBoroughs(user, chatId, messageId, draft);
        }
        if (value === "neighborhoods") {
            draft.location_mode = "neighborhoods";
            draft.borough_ids = [];
            return renderNeighborhoods(user, chatId, messageId, draft);
        }
    }
    if (data.startsWith("borough:")) {
        const value = data.slice(8);
        const geo = await geography();
        if (value === "all") {
            draft.borough_ids = geo.boroughs.map((entry) => entry.id);
        }
        else if (value === "clear") {
            draft.borough_ids = [];
        }
        else if (value === "done") {
            if (!draft.borough_ids.length) {
                return renderBoroughs(user, chatId, messageId, draft);
            }
            return afterSelection(user, chatId, messageId, draft, "rent");
        }
        else {
            const id = Number(value);
            if (geo.boroughs.some((entry) => entry.id === id)) {
                draft.borough_ids = draft.borough_ids.includes(id)
                    ? draft.borough_ids.filter((entry) => entry !== id)
                    : [...draft.borough_ids, id];
            }
        }
        return renderBoroughs(user, chatId, messageId, draft);
    }
    if (data.startsWith("neighborhood:")) {
        const value = data.slice(13);
        const geo = await geography();
        if (value === "all") {
            draft.neighborhood_ids = geo.neighborhoods.map((entry) => entry.id);
        }
        else if (value === "clear") {
            draft.neighborhood_ids = [];
        }
        else if (value === "prev") {
            draft.neighborhood_page = Math.max(0, draft.neighborhood_page - 1);
        }
        else if (value === "next") {
            const pages = Math.max(1, Math.ceil(geo.neighborhoods.length / NEIGHBORHOODS_PER_PAGE));
            draft.neighborhood_page = Math.min(pages - 1, draft.neighborhood_page + 1);
        }
        else if (value === "done") {
            if (!draft.neighborhood_ids.length) {
                return renderNeighborhoods(user, chatId, messageId, draft);
            }
            return afterSelection(user, chatId, messageId, draft, "rent");
        }
        else {
            const id = Number(value);
            if (geo.neighborhoods.some((entry) => entry.id === id)) {
                draft.neighborhood_ids = draft.neighborhood_ids.includes(id)
                    ? draft.neighborhood_ids.filter((entry) => entry !== id)
                    : [...draft.neighborhood_ids, id];
            }
        }
        return renderNeighborhoods(user, chatId, messageId, draft);
    }
    if (data.startsWith("rent:")) {
        const value = data.slice(5);
        if (value === "custom") {
            return renderCustomRent(user, chatId, messageId, draft);
        }
        const amount = Number(value);
        if (RENT_PRESETS.has(amount)) {
            draft.max_warm_rent = amount;
            return afterSelection(user, chatId, messageId, draft, nextSizeStep(draft));
        }
        return renderRent(user, chatId, messageId, draft);
    }
    if (data.startsWith("roomarea:")) {
        return renderRooms(user, chatId, messageId, draft);
    }
    if (data.startsWith("rooms:")) {
        const rooms = Number(data.slice(6));
        if (ROOM_PRESETS.has(rooms)) {
            draft.min_rooms = rooms;
            return afterSelection(user, chatId, messageId, draft, "area");
        }
        return renderRooms(user, chatId, messageId, draft);
    }
    if (data.startsWith("area:")) {
        const area = Number(data.slice(5));
        if (AREA_PRESETS.has(area)) {
            draft.min_area_sqm = area;
            return afterSelection(user, chatId, messageId, draft, "review");
        }
        return renderArea(user, chatId, messageId, draft);
    }
    if (data === "profile:save" || data === "s:save") {
        const issue = validateDraft(draft);
        if (issue)
            return renderStep(user, chatId, messageId, draft, issue);
        const referralReward = await persistProfile(user, draft);
        const result = await edit(chatId, messageId, "✅ Deine Suche ist aktiv. Neue passende Inserate werden automatisch zugestellt.", homeKeyboard({ ...user, onboarding_step: null }));
        if (referralReward?.status === "rewarded") {
            await sendCelebration(chatId, "💎 <b>30 Tage Premium kostenlos aktiviert</b>\n\n" +
                "Dein erstes Suchprofil ist erstellt und dir wurden 30 Tage Premium kostenlos gutgeschrieben.\n\n" +
                "Viel Erfolg und viel Spaß bei deiner Wohnungssuche! 🏠");
        }
        return result;
    }
}

import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { Connector, Source, db, emsg, internalSecret } from "./shared.ts";
import { runScout } from "./scout.ts";
import { runKlein } from "./klein.ts";
import { runGcp } from "./gcp.ts";
import { runImmomio } from "./immomio.ts";
import { runHpm } from "./hpm.ts";
import { runGeneric } from "./generic.ts";
import { runClaimedJob } from "./job-runner.ts";
import { runPublicInventory } from "./public-inventory.ts";
import { runNestpick } from "./nestpick.ts";
import { runCatalog } from "./catalog.ts";
import { runCategoryStreams } from "./category.ts";

async function runPortalRegistryMirror(s:Source){
  const started=new Date().toISOString();
  const portalSourceIds=[1,3];
  const {data,error,count}=await db
    .from("listings")
    .select("last_seen_at",{count:"exact"})
    .in("source_id",portalSourceIds)
    .eq("is_active",true)
    .contains("raw",{provider_source_id:s.id})
    .order("last_seen_at",{ascending:false})
    .limit(1);
  if(error)throw new Error(`portal registry mirror: ${error.message}`);
  const mapped=Math.max(0,Number(count||0));
  const lastPortalSeenAt=data?.[0]?.last_seen_at||null;
  const finished=new Date().toISOString();
  const {error:recordError}=await db.rpc("record_crawl_result",{
    p_source_id:s.id,
    p_started_at:started,
    p_finished_at:finished,
    p_success:true,
    p_connector_priority:1,
    p_connector_label:"portal registry mirror",
    p_fetched_count:mapped,
    p_inserted_count:0,
    p_metadata:{
      architecture:"v3",
      outcome:mapped>0?"success_with_portal_listing":"success_no_portal_inventory",
      strategy:"portal_registry_mirror",
      mirror_source_ids:portalSourceIds,
      provider_source_id:s.id,
      last_portal_seen_at:lastPortalSeenAt,
      complete:false,
    },
    p_error:null,
  });
  if(recordError)throw new Error(`portal registry mirror telemetry: ${recordError.message}`);
  return{
    ok:true,
    source_id:s.id,
    fetched:mapped,
    new:0,
    complete:false,
    mirror_source_ids:portalSourceIds,
    last_portal_seen_at:lastPortalSeenAt,
  };
}
async function processBaseSource(s:Source,connectors:Connector[]){
  const id=s.id;
  if(s.coverage_strategy==="portal_registry_mirror")return runPortalRegistryMirror(s);
  if (id === 1) return runScout(s);
  if (id === 2) return runKlein(s);
  const primary = connectors.find((c) => !c.shadow_only) || connectors[0];
  if(primary && ['source-worker/city-catalog','source-worker/wunder-catalog','source-worker/swap-catalog'].includes(String(primary.config?.adapter)))return runCatalog(s,primary);
  if(primary?.config?.adapter==='source-worker/nestpick-public')return runNestpick(s,primary);
  if(primary && ['source-worker/tag-public','source-worker/urban-public','source-worker/heim-public','source-worker/kaifu-public','source-worker/finken-public','source-worker/buchdrucker-public'].includes(String(primary.config?.adapter)))
    return runPublicInventory(s,primary);
  if (id === 8 && connectors.length) return runGcp(s, connectors);
  if (primary?.connector_kind === "immomio_tenant") return runImmomio(s, primary, connectors.filter(c=>c!==primary));
  if (primary?.connector_kind === "immosolve_api") return runHpm(s, primary);
  return runGeneric(s, connectors);
}
async function processSource(id: number) {
  const { data: source, error } = await db
    .from("sources")
    .select("*,source_connectors(priority,label,connector_kind,enumerable,shadow_only,config,enabled,warmed_at)")
    .eq("id", id)
    .eq("enabled", true)
    .eq("runtime_mode", "live")
    .single();
  if (error || !source) throw new Error(error?.message || "source unavailable");
  const s = source as Source;
  const connectors = (source.source_connectors || [])
    .filter((c: any) => c.enabled)
    .sort((a: any, b: any) => a.priority - b.priority) as Connector[];
  const base=await processBaseSource(s,connectors);
  const category_streams=await runCategoryStreams(s).catch(error=>[{ok:false,error:error instanceof Error?error.message:String(error)}]);
  return {...base,category_streams};
}
async function one(job: any) {
  return runClaimedJob(job, processSource, async (args) => {
    const { data, error } = await db.rpc("finish_source_job_attempt", args);
    if (error) throw new Error(`finish_source_job_attempt: ${error.message}`);
    return data === true;
  });
}
Deno.serve(async (req) => {
  try {
    if (req.method !== "POST")
      return new Response("method not allowed", { status: 405 });
    const internal = await internalSecret();
    if ((req.headers.get("x-internal-secret") || "") !== internal)
      return new Response("unauthorized", { status: 401 });
    if ((await req.json().catch(()=>({}))).dry_run) {
      const {error}=await db.from('sources').select('id').limit(1);
      if(error)throw error;return Response.json({ok:true,dry_run:true});
    }
    const started = Date.now();
    let claimed = 0;
    const results: any[] = [];
    while (Date.now() - started < 50000) {
      const { data: jobs, error } = await db.rpc("claim_source_jobs", {
        p_worker: "source-worker",
        p_qty: 1,
      });
      if (error) throw error;
      if (!jobs?.length) break;
      claimed += jobs.length;
      const batch = await Promise.allSettled(jobs.map((j: any) => one(j)));
      for (const item of batch) {
        if (item.status === "fulfilled") results.push(item.value);
        else throw item.reason;
      }
      // Large portal parsers need their own invocation CPU budget.
      if (jobs.some((job: any) => [1, 2, 3].includes(Number(job.source_id)))) break;
    }
    return Response.json({ ok: true, architecture: "v3", claimed, results });
  } catch (e) {
    return Response.json({ ok: false, error: emsg(e) }, { status: 500 });
  }
});

