    const result = checked(
      await db.rpc("ingest_listing_batch_v3", {
        p_source_id: source.id,
        p_rows: rows.slice(i, i + 100),
        p_presence_epoch: presenceEpoch,
      }),
      "ingest listing batch v3",
    );
