    const url=new URL(raw);
    if(url.protocol!=='https:' || url.hostname!=='www.kleinanzeigen.de' || url.port || url.username || url.password || !/^\/s-(?:wohnung-mieten|haus-mieten|auf-zeit-wg)\//.test(url.pathname))
