        picked.enumerable &&
        ["tenant_api", "full_page"].includes(source.coverage_strategy) &&
        picked.priority === effectivePrimaryPriority);
    const saved =
      savedOverride || (await persistCandidates(source, cands, trustedSnapshot));
    if (
      successfulLaneCount <= 1 &&
      complete &&
      picked.enumerable &&
      source.baseline_completed_at &&
      picked.priority === effectivePrimaryPriority
    ) {
      if (source.coverage_strategy === "pagination") {
        const { data: coverageState } = await databaseQuery(
          db
            .from("source_coverage_state")
            .select("cycle_started_at")
            .eq("source_id", source.id)
            .maybeSingle(),
        );
        await databaseQuery(
          db
            .from("listings")
            .update({ is_active: false })
            .eq("source_id", source.id)
            .eq("is_active", true)
            .lt("last_seen_at", coverageState?.cycle_started_at || started),
        );
      } else {
        const { error: reconcileError } = await db.rpc(
          "deactivate_missing_source_listings",
          {
            p_source_id: source.id,
            p_keys: saved.keys || [],
          },
        );
        if (reconcileError)
          throw new CrawlDatabaseError(
            `Snapshot reconciliation failed: ${reconcileError.message}`,
          );
      }
    }
    const freshDeliveryMode =
      source.coverage_strategy === "pagination"
        ? meta.freshness_mode
        : successfulLaneCount > 1
          ? "primary_plus_additive_new_only"
          : trustedSnapshot
            ? "complete_snapshot"
            : picked.config?.freshness_mode === "newest_first"
              ? "newest_first"
              : "blocked_unverified";
    await markSuccess(source, started, picked, cands.length, saved.fresh, {
      strategy: source.coverage_strategy,
      fresh_delivery_mode: freshDeliveryMode,
      complete,
      multi_connector: successfulLaneCount > 1,
      connector_success_count: successfulLaneCount,
      ...meta,
    });
    return {
      ok: true,
      source_id: source.id,
      fetched: cands.length,
      new: saved.fresh,
      complete,
      multi_connector: successfulLaneCount > 1,
      connector_success_count: successfulLaneCount,
    };
  } catch (e) {
    return markFailure(source, started, e);
  }
}

export type SourceJob = { job_id: string; source_id: number; attempt: number };
type FinishArgs = {
  p_job_id: string;
  p_attempt: number;
  p_success: boolean;
  p_error: string | null;
};

// A failed acknowledgement is not a failed crawl. Do not call finish twice:
// the first RPC may have committed before its HTTP response was lost.
export async function runClaimedJob(
  job: SourceJob,
  process: (sourceId: number) => Promise<any>,
  finish: (args: FinishArgs) => Promise<boolean>,
) {
  let result: any;
  try {
    result = await process(Number(job.source_id));
  } catch (error) {
    result = {
      ok: false,
      source_id: job.source_id,
      error: error instanceof Error ? error.message : String(error),
    };
  }
  const success = result?.ok !== false;
  const accepted = await finish({
    p_job_id: job.job_id,
    p_attempt: job.attempt,
    p_success: success,
    p_error: success ? null : JSON.stringify(result).slice(0, 1200),
  });
  if (!accepted)
    throw new Error(`Source job ${job.job_id}: lease no longer owned`);
  return result;
}

